void insert(
    QuadNode& node,
    Item item)
{
    // If children exist and one completely
    // contains the item, descend.
    if (node.hasChildren())
    {
        if (QuadNode* child =
                containingChild(
                    node,
                    item.bounds))
        {
            insert(*child, item);
            return;
        }
    }

    node.items.push_back(item);

    // Split only after capacity is exceeded
    // and maximum depth is not reached.
    if (node.items.size() >
            MaxItemsPerNode &&
        node.depth < MaxDepth)
    {
        if (!node.hasChildren())
            subdivide(node);

        redistributeItems(node);
    }
}

struct Node final
{
    SpatialIndex PointIndex;
    SpatialIndex Left;
    SpatialIndex Right;
    std::uint32_t Axis;
};

void rangeSearch(
    NodeIndex nodeIndex,
    const AABB& query,
    std::vector<PointID>& output)
{
    if (nodeIndex == Invalid)
        return;

    const Node& node =
        nodes[nodeIndex];

    const Point& p =
        points[node.pointIndex];

    if (query.contains(p.position))
        output.push_back(p.id);

    const float split =
        p.position[node.axis];

    if (query.min[node.axis] <= split)
    {
        rangeSearch(
            node.left,
            query,
            output);
    }

    if (query.max[node.axis] >= split)
    {
        rangeSearch(
            node.right,
            query,
            output);
    }
}

